# cloudflow-plotting: the plotting routines as their own distribution.
# It installs into the cloudflow namespace as cloudflow.plotting.
# Read by exportit/tools/export.py; described in exportit/MAP.md.
# The paths it takes lie under cloudflow/, which cloudflow.map covers.

copy cloudflow/plotting/    src/cloudflow/plotting/

# Needs model output under /com; not a test that pytest can run.
copy cloudflow/tests/test.plotting.py    legacy-tests/test.plotting.py

copy cloudflow/plotting_reqs.reference   requirements/plotting_reqs.reference

# The setup.py that built the old "plotting" distribution.
# Superseded by pyproject.toml; kept for the record.
copy cloudflow/setup.py     legacy/setup.py

# Files that exist only in the unit.
new README.md
new LICENSE                 # a copy of the repository's LICENSE
new pyproject.toml
new uv.lock
new Justfile
new .python-version
new tests/
